def priority(task, state, c=1.0, k=0.5):
    ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    urgency = 1.0 / max(task.estimated_runtime, 1e-6)
    exp_factor = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return (1e6 if ratio >= c else 0.0) + urgency * exp_factor  # tuned (c=0.844,k=1.79)

